from __future__ import annotations

import copy
import json
import os
import re
import signal
import shutil
import subprocess
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from typing import Any
from uuid import uuid4


WORKSPACE_ROOT = Path(__file__).resolve().parents[2]
CHECKPOINT_ROOT = WORKSPACE_ROOT / ".agent-studio" / "checkpoints"
MODEL_ENDPOINT = ""
MODEL_NAME = "abliterated-model-large"
MAX_FILE_BYTES = 600_000
IGNORED_PARTS = {
    ".git",
    ".agents",
    ".cache",
    "node_modules",
    ".agent-studio",
    "dist",
    "build",
    "__pycache__",
}
TREE_HIDDEN_PARTS = IGNORED_PARTS | {".local"}
SNAPSHOT_IGNORED_PARTS = IGNORED_PARTS | {".local"}
SKILL_ROOTS = (
    (WORKSPACE_ROOT / ".local" / "skills", "core"),
    (WORKSPACE_ROOT / ".local" / "secondary_skills", "secondary"),
)
PROCESS_REGISTRY: dict[str, dict[str, Any]] = {}
SENSITIVE_NAMES = {
    ".env",
    ".env.local",
    ".env.production",
    "ABLITERATION_API_KEY",
    "SESSION_SECRET",
}
LANGUAGES = {
    ".ts": "typescript",
    ".tsx": "typescript",
    ".js": "javascript",
    ".jsx": "javascript",
    ".py": "python",
    ".json": "json",
    ".yaml": "yaml",
    ".yml": "yaml",
    ".css": "css",
    ".html": "html",
    ".md": "markdown",
    ".sql": "sql",
    ".sh": "shell",
}


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def resolve_workspace_path(relative_path: str, *, allow_missing: bool = False) -> Path:
    candidate = (WORKSPACE_ROOT / relative_path).resolve()
    if candidate != WORKSPACE_ROOT and WORKSPACE_ROOT not in candidate.parents:
        raise ValueError("Path must stay inside the workspace.")
    if any(part in IGNORED_PARTS for part in candidate.relative_to(WORKSPACE_ROOT).parts):
        raise ValueError("This workspace area is not available to the agent.")
    if candidate.name in SENSITIVE_NAMES:
        raise ValueError("Sensitive files cannot be accessed.")
    if not allow_missing and not candidate.exists():
        raise FileNotFoundError(relative_path)
    return candidate


def language_for(path: Path) -> str | None:
    return LANGUAGES.get(path.suffix.lower())


def entry_for(path: Path) -> dict[str, Any]:
    stat = path.stat()
    relative = path.relative_to(WORKSPACE_ROOT).as_posix()
    return {
        "path": relative,
        "name": path.name,
        "kind": "directory" if path.is_dir() else "file",
        "size": 0 if path.is_dir() else stat.st_size,
        "modifiedAt": datetime.fromtimestamp(stat.st_mtime, timezone.utc).isoformat(),
        "language": None if path.is_dir() else language_for(path),
    }


def list_tree(relative_path: str) -> dict[str, Any]:
    root = resolve_workspace_path(relative_path or "")
    entries: list[dict[str, Any]] = []
    candidates = [root] if root.is_file() else sorted(root.rglob("*"), key=lambda item: (item.is_file(), item.as_posix().lower()))
    for child in candidates:
        try:
            relative = child.relative_to(WORKSPACE_ROOT)
            if child.name in SENSITIVE_NAMES or any(part in TREE_HIDDEN_PARTS for part in relative.parts):
                continue
            entries.append(entry_for(child))
        except (FileNotFoundError, OSError):
            continue
    return {"root": relative_path or "", "entries": entries}


def skill_source_for(path: Path) -> str:
    return "secondary" if "secondary_skills" in path.parts else "core"


def parse_skill(path: Path) -> dict[str, Any]:
    content = path.read_text(encoding="utf-8", errors="replace")
    name = path.parent.name
    description = "Project skill instructions."
    frontmatter = re.search(r"^---\s*(.*?)\s*---", content, re.MULTILINE | re.DOTALL)
    if frontmatter:
        name_match = re.search(r"^name:\s*(.+)$", frontmatter.group(1), re.MULTILINE)
        description_match = re.search(r"^description:\s*(.+)$", frontmatter.group(1), re.MULTILINE)
        if name_match:
            name = name_match.group(1).strip().strip("\"'")
        if description_match:
            description = description_match.group(1).strip().strip("\"'")
    return {
        "name": name,
        "description": description,
        "path": path.relative_to(WORKSPACE_ROOT).as_posix(),
        "source": skill_source_for(path),
        "content": content,
    }


def search_skills(query: str) -> list[dict[str, Any]]:
    needle = query.strip().lower()
    matches: list[dict[str, Any]] = []
    for root, _source in SKILL_ROOTS:
        if not root.exists():
            continue
        for path in root.glob("*/SKILL.md"):
            try:
                skill = parse_skill(path)
            except OSError:
                continue
            haystack = f"{skill['name']} {skill['description']} {skill['path']}".lower()
            if not needle or needle in haystack:
                matches.append({key: skill[key] for key in ("name", "description", "path", "source")})
    return sorted(matches, key=lambda item: (item["source"], item["name"].lower()))[:120]


def read_skill(relative_path: str) -> dict[str, Any]:
    path = resolve_workspace_path(relative_path)
    if path.name != "SKILL.md" or not any(root in path.parents for root, _source in SKILL_ROOTS):
        raise ValueError("Only project SKILL.md documents can be opened with this tool.")
    return parse_skill(path)


def read_file(relative_path: str) -> dict[str, Any]:
    path = resolve_workspace_path(relative_path)
    if not path.is_file():
        raise ValueError("The requested path is not a file.")
    if path.stat().st_size > MAX_FILE_BYTES:
        raise ValueError("File is too large to open in the workspace panel.")
    content = path.read_text(encoding="utf-8", errors="replace")
    stat = path.stat()
    return {
        "path": relative_path,
        "content": content,
        "language": language_for(path),
        "size": stat.st_size,
        "modifiedAt": datetime.fromtimestamp(stat.st_mtime, timezone.utc).isoformat(),
    }


def write_file(relative_path: str, content: str) -> dict[str, Any]:
    path = resolve_workspace_path(relative_path, allow_missing=True)
    if len(content.encode("utf-8")) > MAX_FILE_BYTES:
        raise ValueError("File is too large to write through the workspace panel.")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")
    return read_file(relative_path)


def blocked_command(command: str) -> bool:
    blocked_patterns = [
        r"\brm\s+-rf\s+/",
        r"\bmkfs\b",
        r"\bdd\s+if=",
        r"\bshutdown\b",
        r"\breboot\b",
        r"\bkillall\b",
        r"\bchmod\s+777\b",
        r"\bcurl\b.*\|\s*(sh|bash)",
        r"\bwget\b.*\|\s*(sh|bash)",
        r">\s*/dev/",
    ]
    return any(re.search(pattern, command, re.IGNORECASE) for pattern in blocked_patterns)


def run_command(command: str, cwd: str, timeout_ms: int) -> dict[str, Any]:
    if not command.strip():
        raise ValueError("Command cannot be empty.")
    if blocked_command(command):
        return {
            "command": command,
            "cwd": cwd or "",
            "stdout": "",
            "stderr": "Command blocked by the workspace safety policy.",
            "exitCode": 126,
            "durationMs": 0,
            "blocked": True,
        }
    working_dir = resolve_workspace_path(cwd or "", allow_missing=False)
    if not working_dir.is_dir():
        raise ValueError("Command working directory must be a directory.")
    started = time.perf_counter()
    try:
        result = subprocess.run(
            command,
            cwd=working_dir,
            shell=True,
            capture_output=True,
            text=True,
            timeout=max(1, min(timeout_ms, 120_000)) / 1000,
            env={**os.environ, "PYTHONUNBUFFERED": "1"},
        )
        stdout, stderr, exit_code = result.stdout, result.stderr, result.returncode
    except subprocess.TimeoutExpired as exc:
        stdout = exc.stdout or ""
        stderr = (exc.stderr or "") + "\nCommand timed out."
        exit_code = 124
    duration_ms = round((time.perf_counter() - started) * 1000)
    return {
        "command": command,
        "cwd": cwd or "",
        "stdout": stdout[-30_000:],
        "stderr": stderr[-30_000:],
        "exitCode": exit_code,
        "durationMs": duration_ms,
        "blocked": False,
    }


def process_info(process_id: str, item: dict[str, Any]) -> dict[str, Any]:
    process = item["process"]
    if item["status"] == "running" and process.poll() is not None:
        item["status"] = "exited"
    return {
        "id": process_id,
        "label": item["label"],
        "command": item["command"],
        "cwd": item["cwd"],
        "pid": process.pid,
        "status": item["status"],
        "startedAt": item["startedAt"],
        "port": item["port"],
        "logPath": item["logPath"],
    }


def start_process(command: str, cwd: str, label: str, port: int | None) -> dict[str, Any]:
    if not command.strip():
        raise ValueError("Process command cannot be empty.")
    if blocked_command(command):
        raise ValueError("Process command blocked by the workspace safety policy.")
    working_dir = resolve_workspace_path(cwd or "", allow_missing=False)
    if not working_dir.is_dir():
        raise ValueError("Process working directory must be a directory.")
    process_id = uuid4().hex[:12]
    log_dir = WORKSPACE_ROOT / ".agent-studio" / "processes"
    log_dir.mkdir(parents=True, exist_ok=True)
    log_path = log_dir / f"{process_id}.log"
    log_handle = log_path.open("a", encoding="utf-8")
    try:
        process = subprocess.Popen(
            command,
            cwd=working_dir,
            shell=True,
            stdout=log_handle,
            stderr=subprocess.STDOUT,
            stdin=subprocess.DEVNULL,
            start_new_session=True,
            env={**os.environ, "PYTHONUNBUFFERED": "1"},
        )
    finally:
        log_handle.close()
    item = {
        "process": process,
        "label": label or command.split()[0],
        "command": command,
        "cwd": cwd or "",
        "startedAt": utc_now(),
        "port": port,
        "status": "running",
        "logPath": log_path.relative_to(WORKSPACE_ROOT).as_posix(),
    }
    PROCESS_REGISTRY[process_id] = item
    return process_info(process_id, item)


def list_processes() -> list[dict[str, Any]]:
    return [process_info(process_id, item) for process_id, item in reversed(list(PROCESS_REGISTRY.items()))]


def stop_process(process_id: str) -> dict[str, Any]:
    item = PROCESS_REGISTRY.get(process_id)
    if not item:
        raise FileNotFoundError(process_id)
    process = item["process"]
    if process.poll() is None:
        try:
            os.killpg(process.pid, signal.SIGTERM)
        except ProcessLookupError:
            pass
        item["status"] = "stopped"
    else:
        item["status"] = "exited"
    return process_info(process_id, item)


def checkpoint_snapshot(label: str) -> dict[str, Any]:
    checkpoint_id = f"{datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S')}-{uuid4().hex[:6]}"
    destination = CHECKPOINT_ROOT / checkpoint_id
    destination.mkdir(parents=True, exist_ok=False)
    file_count = 0
    total_bytes = 0
    manifest: list[str] = []
    for source in WORKSPACE_ROOT.rglob("*"):
        if not source.is_file():
            continue
        try:
            relative = source.relative_to(WORKSPACE_ROOT)
            if any(part in SNAPSHOT_IGNORED_PARTS for part in relative.parts) or source.name in SENSITIVE_NAMES:
                continue
            target = destination / relative
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source, target)
            file_count += 1
            total_bytes += source.stat().st_size
            manifest.append(relative.as_posix())
        except (OSError, ValueError):
            continue
    metadata = {
        "id": checkpoint_id,
        "label": label,
        "createdAt": utc_now(),
        "fileCount": file_count,
        "totalBytes": total_bytes,
    }
    (destination / "checkpoint.json").write_text(json.dumps(metadata), encoding="utf-8")
    (destination / "manifest.json").write_text(json.dumps(manifest), encoding="utf-8")
    return metadata


def list_checkpoints() -> list[dict[str, Any]]:
    if not CHECKPOINT_ROOT.exists():
        return []
    results: list[dict[str, Any]] = []
    for folder in sorted(CHECKPOINT_ROOT.iterdir(), reverse=True):
        metadata_file = folder / "checkpoint.json"
        if not metadata_file.exists():
            continue
        try:
            results.append(json.loads(metadata_file.read_text(encoding="utf-8")))
        except (OSError, json.JSONDecodeError):
            continue
    return results[:30]


def restore_checkpoint(checkpoint_id: str) -> dict[str, Any]:
    if not re.fullmatch(r"[0-9]{8}-[0-9]{6}-[a-f0-9]{6}", checkpoint_id):
        raise ValueError("Invalid checkpoint id.")
    source_root = CHECKPOINT_ROOT / checkpoint_id
    metadata_file = source_root / "checkpoint.json"
    manifest_file = source_root / "manifest.json"
    if not metadata_file.exists() or not manifest_file.exists():
        raise FileNotFoundError(checkpoint_id)
    metadata = json.loads(metadata_file.read_text(encoding="utf-8"))
    manifest = set(json.loads(manifest_file.read_text(encoding="utf-8")))
    checkpoint_snapshot(f"Before restoring {metadata.get('label', checkpoint_id)}")
    for source in WORKSPACE_ROOT.rglob("*"):
        if not source.is_file():
            continue
        try:
            relative = source.relative_to(WORKSPACE_ROOT)
            if any(part in SNAPSHOT_IGNORED_PARTS for part in relative.parts) or source.name in SENSITIVE_NAMES:
                continue
            if relative.as_posix() not in manifest:
                source.unlink()
        except (OSError, ValueError):
            continue
    for source in source_root.rglob("*"):
        if not source.is_file() or source.name in {"checkpoint.json", "manifest.json"}:
            continue
        relative = source.relative_to(source_root)
        target = WORKSPACE_ROOT / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source, target)
    return metadata


def workspace_context() -> str:
    lines: list[str] = []
    for candidate in sorted(WORKSPACE_ROOT.iterdir(), key=lambda item: item.name.lower()):
        if candidate.name in IGNORED_PARTS or candidate.name in SENSITIVE_NAMES:
            continue
        lines.append(entry_for(candidate)["path"])
    return "\n".join(lines[:160])


AGENT_SYSTEM_PROMPT = """You are Agent Studio, an autonomous coding agent operating inside a real project workspace.
You work in short, verifiable steps. You may inspect files, edit files, run safe project commands, and create checkpoints.
Never invent that a tool ran. Never expose secrets. Do not touch .env files, node_modules, .git, or hidden credentials.
The project skill catalog is available under .local/skills and .local/secondary_skills. Search it before using a specialized workflow, then read the matching SKILL.md in full.
When the user asks for implementation, use the available tools instead of merely explaining code.

Return exactly one JSON object and nothing else:
{"kind":"message","content":"Return a complete response."}
or
{"kind":"tool","tool":"read_file","path":"relative/path"}
or
{"kind":"tool","tool":"write_file","path":"relative/path","content":"complete file contents"}
or
{"kind":"tool","tool":"run_command","command":"pnpm run typecheck","cwd":"","timeoutMs":120000}
or
{"kind":"tool","tool":"checkpoint","label":"short label"}
or
{"kind":"tool","tool":"search_skills","query":"react vite"}
or
{"kind":"tool","tool":"read_skill","path":".local/skills/react-vite/SKILL.md"}
or
{"kind":"tool","tool":"start_process","command":"pnpm run dev","cwd":"","label":"frontend dev server","port":3000}
or
{"kind":"tool","tool":"list_processes"}
or
{"kind":"tool","tool":"stop_process","id":"process-id"}

Use one tool action per response. After a tool result, continue until the request is complete.
For file writes, provide the complete file content, never ellipses, placeholders, or TODO markers.
Prefer small inspection commands before broad changes, then run an appropriate typecheck or build command.
"""


def model_request(messages: list[dict[str, str]]) -> str:
    api_key = os.environ.get("ABLITERATION_API_KEY")
    if not api_key:
        raise RuntimeError("ABLITERATION_API_KEY is not configured.")
    payload = {
        "temperature": 1,
        "top_p": 1,
        "messages": messages,
        "model": MODEL_NAME,
        "max_tokens": 120000,
        "reasoning_effort": "max",
        "include_reasoning": True,
        "stream": True,
    }
    request = urllib.request.Request(
        MODEL_ENDPOINT,
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        },
        method="POST",
    )
    parts: list[str] = []
    with urllib.request.urlopen(request, timeout=180) as response:
        for raw_line in response:
            line = raw_line.decode("utf-8", errors="replace").strip()
            if not line.startswith("data:"):
                continue
            data = line[5:].strip()
            if data == "[DONE]":
                break
            try:
                event = json.loads(data)
                delta = event.get("choices", [{}])[0].get("delta", {})
                content = delta.get("content")
                if content:
                    parts.append(content)
            except json.JSONDecodeError:
                continue
    return "".join(parts).strip()


def parse_agent_action(text: str) -> dict[str, Any] | None:
    cleaned = text.strip()
    if cleaned.startswith("```"):
        cleaned = re.sub(r"^```(?:json)?\s*", "", cleaned)
        cleaned = re.sub(r"\s*```$", "", cleaned)
    try:
        parsed = json.loads(cleaned)
        return parsed if isinstance(parsed, dict) else None
    except json.JSONDecodeError:
        return None


def run_agent(message: str, history: list[dict[str, str]], context: str | None, emit) -> None:
    messages: list[dict[str, str]] = [
        {"role": "system", "content": AGENT_SYSTEM_PROMPT},
        {
            "role": "system",
            "content": f"Workspace root: {WORKSPACE_ROOT}\nVisible top-level entries:\n{workspace_context()}",
        },
    ]
    messages.extend(
        {"role": item.get("role", "user"), "content": item.get("content", "")}
        for item in history[-12:]
        if item.get("content")
    )
    if context:
        messages.append({"role": "system", "content": f"User-selected context:\n{context[:40_000]}"})
    messages.append({"role": "user", "content": message})

    for step in range(12):
        emit("activity", {"label": "Thinking", "detail": f"Agent step {step + 1} of 12"})
        try:
            raw = model_request(messages)
        except urllib.error.HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="replace")[:1000]
            emit("error", {"message": f"Model request failed ({exc.code}): {detail}"})
            return
        except (urllib.error.URLError, TimeoutError, RuntimeError) as exc:
            emit("error", {"message": str(exc)})
            return
        action = parse_agent_action(raw)
        if not action:
            emit("message", {"content": raw or "The agent returned an empty response."})
            return
        kind = action.get("kind")
        if kind == "message":
            emit("message", {"content": str(action.get("content", ""))})
            return
        if kind != "tool":
            emit("message", {"content": raw})
            return
        tool = action.get("tool")
        try:
            if tool == "read_file":
                result = read_file(str(action["path"]))
                emit("tool", {"tool": tool, "path": result["path"], "content": result["content"]})
                messages.append({"role": "assistant", "content": json.dumps(action)})
                messages.append({"role": "user", "content": f"Tool result read_file:\n{json.dumps(result)}"})
            elif tool == "write_file":
                result = write_file(str(action["path"]), str(action["content"]))
                emit("tool", {"tool": tool, "path": result["path"], "size": result["size"]})
                messages.append({"role": "assistant", "content": json.dumps(action)})
                messages.append({"role": "user", "content": f"Tool result write_file: {json.dumps(result)}"})
            elif tool == "run_command":
                result = run_command(
                    str(action["command"]),
                    str(action.get("cwd", "")),
                    int(action.get("timeoutMs", 120_000)),
                )
                emit("tool", {"tool": tool, **result})
                messages.append({"role": "assistant", "content": json.dumps(action)})
                messages.append({"role": "user", "content": f"Tool result run_command:\n{json.dumps(result)}"})
            elif tool == "checkpoint":
                result = checkpoint_snapshot(str(action.get("label", "Agent checkpoint")))
                emit("tool", {"tool": tool, **result})
                messages.append({"role": "assistant", "content": json.dumps(action)})
                messages.append({"role": "user", "content": f"Tool result checkpoint: {json.dumps(result)}"})
            elif tool == "search_skills":
                result = search_skills(str(action.get("query", "")))
                emit("tool", {"tool": tool, "query": action.get("query", ""), "skills": result})
                messages.append({"role": "assistant", "content": json.dumps(action)})
                messages.append({"role": "user", "content": f"Tool result search_skills:\n{json.dumps(result)}"})
            elif tool == "read_skill":
                result = read_skill(str(action["path"]))
                emit("tool", {"tool": tool, "path": result["path"], "name": result["name"]})
                messages.append({"role": "assistant", "content": json.dumps(action)})
                messages.append({"role": "user", "content": f"Tool result read_skill:\n{json.dumps(result)}"})
            elif tool == "start_process":
                result = start_process(
                    str(action["command"]),
                    str(action.get("cwd", "")),
                    str(action.get("label", "")),
                    int(action["port"]) if action.get("port") is not None else None,
                )
                emit("tool", {"tool": tool, **result})
                messages.append({"role": "assistant", "content": json.dumps(action)})
                messages.append({"role": "user", "content": f"Tool result start_process: {json.dumps(result)}"})
            elif tool == "list_processes":
                result = list_processes()
                emit("tool", {"tool": tool, "processes": result})
                messages.append({"role": "assistant", "content": json.dumps(action)})
                messages.append({"role": "user", "content": f"Tool result list_processes: {json.dumps(result)}"})
            elif tool == "stop_process":
                result = stop_process(str(action["id"]))
                emit("tool", {"tool": tool, **result})
                messages.append({"role": "assistant", "content": json.dumps(action)})
                messages.append({"role": "user", "content": f"Tool result stop_process: {json.dumps(result)}"})
            else:
                raise ValueError(f"Unknown agent tool: {tool}")
        except (KeyError, ValueError, FileNotFoundError, OSError) as exc:
            emit("tool_error", {"tool": tool, "message": str(exc)})
            messages.append({"role": "user", "content": f"Tool error for {tool}: {exc}"})
    emit("message", {"content": "The agent reached its maximum step count. Review the latest activity and continue with a follow-up request."})


class Handler(BaseHTTPRequestHandler):
    server_version = "AgentStudio/1.0"

    def log_message(self, format: str, *args: Any) -> None:
        return

    def send_json(self, status: int, payload: Any) -> None:
