        cleaned = re.sub(r"\s*```$", "", cleaned)
    try:
        parsed = json.loads(cleaned)
        return parsed if isinstance(parsed, dict) else None
    except json.JSONDecodeError:
        return None


def run_agent(message: str, history: list[dict[str, str]], context: str | None, emit) -> None:
    messages: list[dict[str, str]] = [
        {"role": "system", "content": AGENT_SYSTEM_PROMPT},
        {
            "role": "system",
            "content": f"Workspace root: {WORKSPACE_ROOT}\nVisible top-level entries:\n{workspace_context()}",
        },
    ]
    messages.extend(
        {"role": item.get("role", "user"), "content": item.get("content", "")}
        for item in history[-12:]
        if item.get("content")
    )
    if context:
        messages.append({"role": "system", "content": f"User-selected context:\n{context[:40_000]}"})
    messages.append({"role": "user", "content": message})

    for step in range(12):
        emit("activity", {"label": "Thinking", "detail": f"Agent step {step + 1} of 12"})
        try:
            raw = model_request(messages)
        except urllib.error.HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="replace")[:1000]
            emit("error", {"message": f"Model request failed ({exc.code}): {detail}"})
            return
        except (urllib.error.URLError, TimeoutError, RuntimeError) as exc:
            emit("error", {"message": str(exc)})
            return
        action = parse_agent_action(raw)
        if not action:
            emit("message", {"content": raw or "The agent returned an empty response."})
            return
        kind = action.get("kind")
        if kind == "message":
            emit("message", {"content": str(action.get("content", ""))})
            return
        if kind != "tool":
            emit("message", {"content": raw})
            return
        tool = action.get("tool")
        try:
            if tool == "read_file":
                result = read_file(str(action["path"]))
                emit("tool", {"tool": tool, "path": result["path"], "content": result["content"]})
                messages.append({"role": "assistant", "content": json.dumps(action)})
                messages.append({"role": "user", "content": f"Tool result read_file:\n{json.dumps(result)}"})
            elif tool == "write_file":
                result = write_file(str(action["path"]), str(action["content"]))
                emit("tool", {"tool": tool, "path": result["path"], "size": result["size"]})
                messages.append({"role": "assistant", "content": json.dumps(action)})
                messages.append({"role": "user", "content": f"Tool result write_file: {json.dumps(result)}"})
            elif tool == "run_command":
                result = run_command(
                    str(action["command"]),
                    str(action.get("cwd", "")),
                    int(action.get("timeoutMs", 120_000)),
                )
                emit("tool", {"tool": tool, **result})
                messages.append({"role": "assistant", "content": json.dumps(action)})
                messages.append({"role": "user", "content": f"Tool result run_command:\n{json.dumps(result)}"})
            elif tool == "checkpoint":
                result = checkpoint_snapshot(str(action.get("label", "Agent checkpoint")))
                emit("tool", {"tool": tool, **result})
                messages.append({"role": "assistant", "content": json.dumps(action)})
                messages.append({"role": "user", "content": f"Tool result checkpoint: {json.dumps(result)}"})
            elif tool == "search_skills":
                result = search_skills(str(action.get("query", "")))
                emit("tool", {"tool": tool, "query": action.get("query", ""), "skills": result})
                messages.append({"role": "assistant", "content": json.dumps(action)})
                messages.append({"role": "user", "content": f"Tool result search_skills:\n{json.dumps(result)}"})
            elif tool == "read_skill":
                result = read_skill(str(action["path"]))
                emit("tool", {"tool": tool, "path": result["path"], "name": result["name"]})
                messages.append({"role": "assistant", "content": json.dumps(action)})
                messages.append({"role": "user", "content": f"Tool result read_skill:\n{json.dumps(result)}"})
            elif tool == "start_process":
                result = start_process(
                    str(action["command"]),
                    str(action.get("cwd", "")),
                    str(action.get("label", "")),
                    int(action["port"]) if action.get("port") is not None else None,
                )
                emit("tool", {"tool": tool, **result})
                messages.append({"role": "assistant", "content": json.dumps(action)})
                messages.append({"role": "user", "content": f"Tool result start_process: {json.dumps(result)}"})
            elif tool == "list_processes":
                result = list_processes()
                emit("tool", {"tool": tool, "processes": result})
                messages.append({"role": "assistant", "content": json.dumps(action)})
                messages.append({"role": "user", "content": f"Tool result list_processes: {json.dumps(result)}"})
            elif tool == "stop_process":
                result = stop_process(str(action["id"]))
                emit("tool", {"tool": tool, **result})
                messages.append({"role": "assistant", "content": json.dumps(action)})
                messages.append({"role": "user", "content": f"Tool result stop_process: {json.dumps(result)}"})
            else:
                raise ValueError(f"Unknown agent tool: {tool}")
        except (KeyError, ValueError, FileNotFoundError, OSError) as exc:
            emit("tool_error", {"tool": tool, "message": str(exc)})
            messages.append({"role": "user", "content": f"Tool error for {tool}: {exc}"})
    emit("message", {"content": "The agent reached its maximum step count. Review the latest activity and continue with a follow-up request."})


class Handler(BaseHTTPRequestHandler):
    server_version = "AgentStudio/1.0"

    def log_message(self, format: str, *args: Any) -> None:
        return

    def send_json(self, status: int, payload: Any) -> None:
        encoded = json.dumps(payload).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(encoded)))
        self.send_header("Access-Control-Allow-Origin", "*")
        self.end_headers()
        self.wfile.write(encoded)

    def do_OPTIONS(self) -> None:
        self.send_response(204)
        self.send_header("Access-Control-Allow-Origin", "*")
        self.send_header("Access-Control-Allow-Headers", "Content-Type")
        self.send_header("Access-Control-Allow-Methods", "GET, POST, PUT, OPTIONS")
        self.end_headers()

    def body(self) -> dict[str, Any]:
        length = int(self.headers.get("Content-Length", "0"))
        if length > 2_000_000:
            raise ValueError("Request body is too large.")
        raw = self.rfile.read(length)
        return json.loads(raw.decode("utf-8")) if raw else {}

    def do_GET(self) -> None:
        from urllib.parse import parse_qs, urlparse

        parsed = urlparse(self.path)
        query = parse_qs(parsed.query)
        try:
            if parsed.path == "/api/healthz":
                self.send_json(200, {"status": "ok"})
            elif parsed.path == "/api/workspace/tree":
                self.send_json(200, list_tree(query.get("path", [""])[0]))
            elif parsed.path == "/api/workspace/file":
                self.send_json(200, read_file(query.get("path", [""])[0]))
            elif parsed.path == "/api/workspace/checkpoints":
                self.send_json(200, list_checkpoints())
            elif parsed.path == "/api/workspace/skills":
                self.send_json(200, search_skills(query.get("query", [""])[0]))
            elif parsed.path == "/api/workspace/skill":
                self.send_json(200, read_skill(query.get("path", [""])[0]))
            elif parsed.path == "/api/workspace/processes":
                self.send_json(200, list_processes())
            elif parsed.path == "/api/agent/status":
                self.send_json(
                    200,
                    {
                        "model": MODEL_NAME,
                        "configured": bool(os.environ.get("ABLITERATION_API_KEY")),
                        "endpoint": MODEL_ENDPOINT,
                        "capabilities": ["streaming responses", "workspace files", "safe shell", "checkpoints"],
                    },
                )
            else:
                self.send_json(404, {"error": "Not found"})
        except FileNotFoundError as exc:
            self.send_json(404, {"error": str(exc)})
        except (ValueError, OSError) as exc:
            self.send_json(400, {"error": str(exc)})

    def do_PUT(self) -> None:
        try:
            if self.path != "/api/workspace/file":
                self.send_json(404, {"error": "Not found"})
                return
            payload = self.body()
            self.send_json(200, write_file(str(payload["path"]), str(payload["content"])))
        except (KeyError, ValueError, OSError) as exc:
            self.send_json(400, {"error": str(exc)})

    def do_POST(self) -> None:
        try:
            payload = self.body()
            if self.path == "/api/workspace/command":
                result = run_command(
                    str(payload["command"]),
                    str(payload.get("cwd", "")),
                    int(payload.get("timeoutMs", 120_000)),
                )
                self.send_json(200, result)
            elif self.path == "/api/workspace/processes":
                self.send_json(
                    201,
                    start_process(
                        str(payload["command"]),
                        str(payload.get("cwd", "")),
                        str(payload.get("label", "")),
                        int(payload["port"]) if payload.get("port") is not None else None,
                    ),
                )
            elif self.path == "/api/workspace/checkpoints":
                self.send_json(201, checkpoint_snapshot(str(payload.get("label", "Manual checkpoint"))))
            elif self.path.startswith("/api/workspace/checkpoints/") and self.path.endswith("/restore"):
                checkpoint_id = self.path[len("/api/workspace/checkpoints/") : -len("/restore")]
                self.send_json(200, restore_checkpoint(checkpoint_id))
            elif self.path.startswith("/api/workspace/processes/") and self.path.endswith("/stop"):
                process_id = self.path[len("/api/workspace/processes/") : -len("/stop")]
                self.send_json(200, stop_process(process_id))
            elif self.path == "/api/agent/chat":
                self.send_response(200)
                self.send_header("Content-Type", "text/event-stream; charset=utf-8")
                self.send_header("Cache-Control", "no-cache")
                self.send_header("Connection", "keep-alive")
                self.send_header("Access-Control-Allow-Origin", "*")
                self.end_headers()

                def emit(kind: str, data: dict[str, Any]) -> None:
                    event = json.dumps({"type": kind, **data}).replace("\n", "\\n")
                    self.wfile.write(f"data: {event}\n\n".encode("utf-8"))
                    self.wfile.flush()

                emit("start", {"model": MODEL_NAME})
                run_agent(
                    str(payload.get("message", "")),
                    payload.get("history", []),
                    payload.get("context"),
                    emit,
                )
                emit("done", {})
            else:
                self.send_json(404, {"error": "Not found"})
        except (KeyError, ValueError, OSError, json.JSONDecodeError) as exc:
            self.send_json(400, {"error": str(exc)})


def main() -> None:
    port = int(os.environ.get("PORT", "5000"))
    ThreadingHTTPServer(("0.0.0.0", port), Handler).serve_forever()


if __name__ == "__main__":
    main()
